const struct AwCentre *AW_FindCentre(u16 mapId)
{
    u32 i;

    for (i = 0; i < AW_NUM_CENTRES; i++)
    {
        if (gAwCentres[i].mapId == mapId)
            return &gAwCentres[i];
    }
    return NULL;
}

